/* ============================================
   ICON BUTTON
   A button holding a single icon, shaped by the theme's button radius
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

.ds-icon-button {
  /* Layout */
  display: inline-flex;
  align-items: center;
  justify-content: center;

  /* Size — default: the row height (--control-height-*), as an even box */
  box-sizing: border-box;
  width: var(--control-height-default);
  height: var(--control-height-default);

  /* Shape */
  border-radius: var(--radius-pill); /* the button radius: a circle in a round theme, a square in a square one */

  /* Transitions */
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard), border-color var(--motion-duration-base) var(--motion-ease-standard), opacity var(--motion-duration-base) var(--motion-ease-standard);

  /* Reset */
  cursor: pointer;
  border: none;
  padding: 0;
  text-decoration: none;
  color: inherit;
}

/* ============================================
   SIZE — DEFAULT
   ============================================ */

.ds-icon-button--default {
  width: var(--control-height-default);
  height: var(--control-height-default);
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-icon-button--compact {
  width: var(--control-height-compact);
  height: var(--control-height-compact);
}

.ds-icon-button--compact .ds-icon-button__icon {
  --icon-size: var(--icon-size-500);
}

/* ============================================
   ICON
   ============================================ */

.ds-icon-button__icon {
  flex-shrink: 0;
  --icon-size: var(--icon-size-600);
  line-height: 1;
}

/* A node icon (an avatar, a spinner, an SVG) is laid out as a flex item:
   inline in a block slot it would sit on the text baseline, and the room
   left under it for descenders made the slot taller than the node and
   lifted the node off the button's centre. */
.ds-icon-button__icon:not(.material-symbols-rounded) {
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ============================================
   PRIMARY VARIANT (SOLID)
   ============================================ */

.ds-icon-button--primary {
  background-color: var(--color-action-primary-bg);
  border: none;
}

.ds-icon-button--primary .ds-icon-button__icon {
  color: var(--color-action-primary-text);
}

.ds-icon-button--primary.ds-icon-button--hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-icon-button--primary.ds-icon-button--hover .ds-icon-button__icon {
  color: var(--color-action-primary-text-active);
}

.ds-icon-button--primary.ds-icon-button--active {
  background-color: var(--color-action-primary-bg-active);
}

.ds-icon-button--primary.ds-icon-button--active .ds-icon-button__icon {
  color: var(--color-action-primary-text-active);
}

.ds-icon-button--primary.ds-icon-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-icon-button--primary:not(.ds-icon-button--disabled):hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-icon-button--primary:not(.ds-icon-button--disabled):hover .ds-icon-button__icon {
  color: var(--color-action-primary-text-active);
}

.ds-icon-button--primary:not(.ds-icon-button--disabled):active {
  background-color: var(--color-action-primary-bg-active);
}

.ds-icon-button--primary:not(.ds-icon-button--disabled):active .ds-icon-button__icon {
  color: var(--color-action-primary-text-active);
}

/* ============================================
   SECONDARY VARIANT (OUTLINED)
   ============================================ */

.ds-icon-button--secondary {
  border: var(--border-025) solid var(--color-action-primary-border);
  background-color: transparent;
}

.ds-icon-button--secondary .ds-icon-button__icon {
  color: var(--color-action-icon-default);
}

.ds-icon-button--secondary.ds-icon-button--hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-icon-button--secondary.ds-icon-button--hover .ds-icon-button__icon {
  color: var(--color-action-icon-active);
}

.ds-icon-button--secondary.ds-icon-button--active {
  background-color: var(--color-action-primary-bg-active);
}

.ds-icon-button--secondary.ds-icon-button--active .ds-icon-button__icon {
  color: var(--color-action-icon-active);
}

.ds-icon-button--secondary.ds-icon-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-icon-button--secondary:not(.ds-icon-button--disabled):hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-icon-button--secondary:not(.ds-icon-button--disabled):hover .ds-icon-button__icon {
  color: var(--color-action-icon-active);
}

.ds-icon-button--secondary:not(.ds-icon-button--disabled):active {
  background-color: var(--color-action-primary-bg-active);
}

.ds-icon-button--secondary:not(.ds-icon-button--disabled):active .ds-icon-button__icon {
  color: var(--color-action-icon-active);
}

/* ============================================
   TERTIARY VARIANT (PASSIVE / GHOST)
   ============================================ */

.ds-icon-button--tertiary {
  background-color: var(--color-action-passive-bg);
  border: none;
}

.ds-icon-button--tertiary .ds-icon-button__icon {
  color: var(--color-icon-primary);
}

.ds-icon-button--tertiary.ds-icon-button--hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-icon-button--tertiary.ds-icon-button--active {
  background-color: var(--color-action-passive-bg-active);
}

.ds-icon-button--tertiary.ds-icon-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-icon-button--tertiary:not(.ds-icon-button--disabled):hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-icon-button--tertiary:not(.ds-icon-button--disabled):active {
  background-color: var(--color-action-passive-bg-active);
}

/* ============================================
   PRIMARY × NEUTRAL TONE (SOLID GREY)
   The class the legacy variant="neutral" kept.
   Filled like primary but in the neutral greys —
   unlike tertiary, the background is always shown.
   ============================================ */

.ds-icon-button--neutral {
  background-color: var(--color-action-neutral-bg);
  border: none;
}

.ds-icon-button--neutral .ds-icon-button__icon {
  color: var(--color-action-neutral-text);
}

.ds-icon-button--neutral.ds-icon-button--hover {
  background-color: var(--color-action-neutral-bg-hover);
}

.ds-icon-button--neutral.ds-icon-button--active {
  background-color: var(--color-action-neutral-bg-active);
}

.ds-icon-button--neutral.ds-icon-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-icon-button--neutral:not(.ds-icon-button--disabled):hover {
  background-color: var(--color-action-neutral-bg-hover);
}

.ds-icon-button--neutral:not(.ds-icon-button--disabled):active {
  background-color: var(--color-action-neutral-bg-active);
}

/* ============================================
   SECONDARY × NEUTRAL TONE (OUTLINED GREY)
   variant="secondary" tone="neutral": hover and
   press fill with the solid neutral fills.
   ============================================ */

.ds-icon-button--secondary-neutral {
  border: var(--border-025) solid var(--color-action-neutral-border);
  background-color: transparent;
}

.ds-icon-button--secondary-neutral .ds-icon-button__icon {
  color: var(--color-action-icon-default);
}

.ds-icon-button--secondary-neutral.ds-icon-button--hover {
  background-color: var(--color-action-neutral-bg-hover);
}

.ds-icon-button--secondary-neutral.ds-icon-button--active {
  background-color: var(--color-action-neutral-bg-active);
}

.ds-icon-button--secondary-neutral.ds-icon-button--hover .ds-icon-button__icon,
.ds-icon-button--secondary-neutral.ds-icon-button--active .ds-icon-button__icon {
  color: var(--color-action-neutral-text);
}

.ds-icon-button--secondary-neutral.ds-icon-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-icon-button--secondary-neutral:not(.ds-icon-button--disabled):hover {
  background-color: var(--color-action-neutral-bg-hover);
}

.ds-icon-button--secondary-neutral:not(.ds-icon-button--disabled):active {
  background-color: var(--color-action-neutral-bg-active);
}

.ds-icon-button--secondary-neutral:not(.ds-icon-button--disabled):hover .ds-icon-button__icon,
.ds-icon-button--secondary-neutral:not(.ds-icon-button--disabled):active .ds-icon-button__icon {
  color: var(--color-action-neutral-text);
}

/* ============================================
   PRIMARY DESTRUCTIVE (SOLID DANGER)
   variant="primary" tone="destructive".
   ============================================ */

.ds-icon-button--primary-destructive {
  background-color: var(--color-action-destructive-bg);
  border: none;
}

.ds-icon-button--primary-destructive .ds-icon-button__icon {
  color: var(--color-action-destructive-text);
}

.ds-icon-button--primary-destructive.ds-icon-button--hover {
  background-color: var(--color-action-destructive-bg-hover);
}

.ds-icon-button--primary-destructive.ds-icon-button--active {
  background-color: var(--color-action-destructive-bg-active);
}

.ds-icon-button--primary-destructive.ds-icon-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-icon-button--primary-destructive:not(.ds-icon-button--disabled):hover {
  background-color: var(--color-action-destructive-bg-hover);
}

.ds-icon-button--primary-destructive:not(.ds-icon-button--disabled):active {
  background-color: var(--color-action-destructive-bg-active);
}

/* ============================================
   DESTRUCTIVE TONE (OUTLINED DANGER)
   tone="destructive" at secondary or tertiary
   emphasis: Button's outlined danger look on the
   button, filling with the danger colour on hover
   and press.
   ============================================ */

.ds-icon-button--destructive {
  border: var(--border-025) solid var(--color-action-destructive-border);
  background-color: transparent;
}

.ds-icon-button--destructive .ds-icon-button__icon {
  color: var(--color-action-destructive-text-secondary);
}

.ds-icon-button--destructive.ds-icon-button--hover,
.ds-icon-button--destructive.ds-icon-button--active {
  background-color: var(--color-action-destructive-bg);
}

.ds-icon-button--destructive.ds-icon-button--hover .ds-icon-button__icon,
.ds-icon-button--destructive.ds-icon-button--active .ds-icon-button__icon {
  color: var(--color-action-destructive-text);
}

.ds-icon-button--destructive.ds-icon-button--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Interactive hover/active */
.ds-icon-button--destructive:not(.ds-icon-button--disabled):hover,
.ds-icon-button--destructive:not(.ds-icon-button--disabled):active {
  background-color: var(--color-action-destructive-bg);
}

.ds-icon-button--destructive:not(.ds-icon-button--disabled):hover .ds-icon-button__icon,
.ds-icon-button--destructive:not(.ds-icon-button--disabled):active .ds-icon-button__icon {
  color: var(--color-action-destructive-text);
}

/* ============================================
   LOADING
   Keeps the variant's full-colour appearance (no disabled dim);
   the spinner replaces the icon and inherits its colour.
   ============================================ */

.ds-icon-button--loading {
  cursor: progress;
  pointer-events: none;
}

/* The spinner is a box, not a glyph: left inline, it sits on the text
   baseline and the strut's descender pushes it ~1px above the button's
   centre. Flex centres it geometrically. */
.ds-icon-button--loading .ds-icon-button__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ============================================
   FOCUS
   ============================================ */

.ds-icon-button:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* ============================================
   BADGE
   A count or a dot on the top-end corner, in
   BottomNav's count-badge treatment.
   ============================================ */

.ds-icon-button--badged {
  position: relative;
}

.ds-icon-button__badge {
  position: absolute;
  inset-block-start: calc(var(--padding-100) * -1);
  inset-inline-end: calc(var(--padding-100) * -1);
  box-sizing: border-box;
  min-width: 16px;
  height: 16px;
  padding: 0 var(--padding-100);
  border-radius: var(--radius-pill);
  background-color: var(--color-count-badge-bg);
  color: var(--color-count-badge-text);
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-caption-line-height);
  text-align: center;
  white-space: nowrap;
  pointer-events: none;
}

.ds-icon-button__badge--dot {
  inset-block-start: var(--padding-050);
  inset-inline-end: var(--padding-050);
  min-width: 0;
  width: 8px;
  height: 8px;
  padding: 0;
}

} /* @layer rift.components */

// No 'use client' directive: IconButton defines no hooks or handlers of its
// own — consumers' event props fall through — so Server Components can render it.
// The default Tooltip wrapper is the client island; like MessageActions, the
// button itself stays server-renderable.
import React from 'react';
import type { LinkComponent } from '../../behaviors/LinkProvider';
import { Spinner } from '../Spinner/Spinner';
import { Tooltip } from '../Tooltip/Tooltip';
import './IconButton.css';
import '../../fonts/material-symbols.css';
import { mirrorClass } from '../../behaviors/direction';
import { DEFAULT_LOCALE, formatNumber } from '../../behaviors/locale';

/** Props owned by IconButton itself — everything else falls through to the DOM node. */
type IconButtonOwnProps = {
  /** The icon — Material Symbol name (string) or custom element (ReactNode) */
  icon: string | React.ReactNode;
  /**
   * Emphasis: `primary` (filled), `secondary` (outlined) or `tertiary`
   * (ghost). The colour is `tone`'s job. `neutral` is the legacy value from
   * before the split and renders as `variant="primary" tone="neutral"`.
   */
  variant?: 'primary' | 'secondary' | 'tertiary' | 'neutral';
  /**
   * Colour, independent of emphasis: `default` carries the action colour,
   * `neutral` the greys, `destructive` the danger colour. Tertiary is
   * already grey, so `neutral` leaves it unchanged; a tertiary
   * `destructive` takes the outlined look, since a danger action needs a
   * visible edge.
   */
  tone?: 'default' | 'neutral' | 'destructive';
  /**
   * Legacy alias for `variant`.
   *
   * @deprecated Use `variant` instead.
   */
  priority?: 'primary' | 'secondary' | 'tertiary';
  /** Whether the button is disabled */
  disabled?: boolean;
  /**
   * Documentation-only interaction state.
   *
   * @deprecated Use `disabled` for the disabled state.
   *
   * Documentation-only affordance for rendering a *static* interaction state in
   * Storybook and the showcase site. Real hover/active styling comes from CSS
   * pseudo-classes and needs no prop — for docs, prefer
   * `className="ds-icon-button--hover"`.
   */
  state?: 'default' | 'hover' | 'active' | 'disabled';
  /** Button size */
  size?: 'default' | 'compact';
  /**
   * Shows a spinner in place of the icon and blocks interaction while an
   * async action runs. Keeps the variant's full-colour appearance (unlike
   * the disabled state) and sets `aria-busy` on the rendered element.
   */
  loading?: boolean;
  /**
   * The button's name: what a screen reader announces and, by default, what
   * the tooltip shows. Required, because the button has no visible text.
   * Named as Button's and AiButton's text is, so the family spells it one way.
   */
  label: string;
  /**
   * The hover/focus tooltip. An icon-only control names itself: by default
   * the button wears a Tooltip carrying `label`. Pass a string to show
   * different wording, or `false` to opt out — for a host that labels the
   * control another way, or one that owns the button's box directly
   * (SplitButton's trigger stretches to its sibling segment, which the
   * tooltip wrapper would block).
   */
  tooltip?: string | false;
  /** Which side the tooltip opens on. `start` and `end` follow the reading direction. */
  tooltipPosition?: 'top' | 'bottom' | 'left' | 'right' | 'start' | 'end';
  /** Optional href — renders as <a> instead of <button> */
  href?: string;
  /** Optional target attribute for links */
  target?: string;
  /** Optional rel attribute for links */
  rel?: string;
  /** A mark on the button's top-end corner, as BottomNav draws one: a count (a notification bell's unread), or `true` for a dot with no number. */
  badge?: number | string | true;
  /** The highest count the badge spells out; a larger one reads "99+". Defaults to 99. */
  badgeMax?: number;
  /**
   * Text read after `label` while the button carries a badge, given the
   * badge. Defaults to ", new" for a dot and ", 3 new" for a count; the
   * leading comma and space are part of the text. The tooltip keeps
   * `label` alone.
   */
  badgeLabel?: (badge: number | string | true) => string;
  /** The BCP 47 locale a numeric badge is written in, such as `ar-EG`. Defaults to `en-US`. This component can render from a Server Component, so it takes the prop alone and reads no LocaleProvider. */
  locale?: string;
  /** Additional CSS classes */
  className?: string;
  /**
   * The component the link renders with, such as Next.js's `Link`, so it
   * navigates through the app's router; a plain `<a>` when unset. This
   * component can render on the server, so it never reads a LinkProvider:
   * pass the prop even under one.
   */
  linkComponent?: LinkComponent;
};

export interface IconButtonProps
  extends IconButtonOwnProps,
    Omit<React.ComponentPropsWithoutRef<'button'>, keyof IconButtonOwnProps | 'type'> {}

/**
 * The emphasis × tone cell the button renders, as its modifier class, named
 * like Button's. Filled grey keeps its original `neutral` class, so styles
 * written against it still apply.
 */
function resolveIconButtonCell(
  variant: NonNullable<IconButtonOwnProps['variant']>,
  tone: IconButtonOwnProps['tone'],
): string {
  const emphasis = variant === 'neutral' ? 'primary' : variant;
  const resolvedTone = tone ?? (variant === 'neutral' ? 'neutral' : 'default');
  if (resolvedTone === 'destructive') {
    return emphasis === 'primary' ? 'primary-destructive' : 'destructive';
  }
  if (resolvedTone === 'neutral' && emphasis !== 'tertiary') {
    return emphasis === 'primary' ? 'neutral' : 'secondary-neutral';
  }
  return emphasis;
}

/**
 * Icon button component.
 * A button holding a single icon and no visible text, round or square as
 * the theme's button radius makes it. `variant` sets the emphasis
 * (primary, secondary, tertiary) and `tone` the colour (default, neutral,
 * destructive),
 * in default and compact sizes.
 *
 * Renders a `<button>`, or an `<a>` when `href` is supplied. Forwards a ref to
 * whichever element it renders, and spreads unrecognised props onto it.
 */
export const IconButton = React.forwardRef<
  HTMLButtonElement | HTMLAnchorElement,
  IconButtonProps
>(
  (
    {
      icon,
      variant,
      tone,
      priority,
      disabled,
      state,
      size = 'default',
      loading,
      label,
      tooltip,
      tooltipPosition = 'top',
      href,
      target,
      rel,
      badge,
      badgeMax = 99,
      badgeLabel = defaultBadgeLabel,
      locale = DEFAULT_LOCALE,
      className = '',
      linkComponent,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-icon-button';
    const Link = linkComponent ?? 'a';

    // `priority` is the deprecated spelling of `variant`; `variant` wins when both are set.
    const resolvedVariant = resolveIconButtonCell(variant ?? priority ?? 'primary', tone);
    // `disabled` is the real prop; `state="disabled"` is the deprecated path.
    const isDisabled = disabled ?? state === 'disabled';
    // Keep the state modifier class so the disabled styling applies either way.
    const resolvedState = state ?? (isDisabled ? 'disabled' : 'default');
    const isLoading = Boolean(loading);

    const classes = [
      baseClass,
      `${baseClass}--${resolvedVariant}`,
      `${baseClass}--${resolvedState}`,
      `${baseClass}--${size}`,
      isLoading && `${baseClass}--loading`,
      badge !== undefined && `${baseClass}--badged`,
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const glyph = isLoading ? (
      <span className={`${baseClass}__icon`} aria-hidden="true">
        <Spinner size={size === 'compact' ? 'sm' : 'md'} tone="inherit" />
      </span>
    ) : (
      <span className={`${baseClass}__icon${typeof icon === 'string' ? ` material-symbols-rounded ${mirrorClass(icon)}` : ''}`} aria-hidden="true">
        {icon}
      </span>
    );
    const badgeText =
      badge === undefined || badge === true
        ? null
        : typeof badge === 'number'
          ? badge > badgeMax
            ? `${formatNumber(badgeMax, locale)}+`
            : formatNumber(badge, locale)
          : badge;
    const children = (
      <>
        {glyph}
        {badge === true && <span className={`${baseClass}__badge ${baseClass}__badge--dot`} aria-hidden="true" />}
        {badgeText !== null && (
          <span className={`${baseClass}__badge`} aria-hidden="true">
            {badgeText}
          </span>
        )}
      </>
    );
    const accessibleName = badge === undefined ? label : `${label}${badgeLabel(badge)}`;

    // A loading link renders the button branch so interaction is truly blocked.
    const control =
      href && !isDisabled && !isLoading ? (
        <Link
          {...(rest as React.ComponentPropsWithoutRef<'a'>)}
          ref={ref as React.Ref<HTMLAnchorElement>}
          className={classes}
          href={href}
          target={target}
          rel={rel}
          aria-label={accessibleName}
        >
          {children}
        </Link>
      ) : (
        <button
          {...rest}
          ref={ref as React.Ref<HTMLButtonElement>}
          type="button"
          className={classes}
          disabled={isDisabled || isLoading}
          aria-busy={isLoading || undefined}
          aria-label={accessibleName}
        >
          {children}
        </button>
      );

    // Self-labelling: the tooltip repeats the accessible name unless the
    // caller overrides the wording or opts out.
    const tooltipContent = tooltip === false ? null : (tooltip ?? label);
    if (!tooltipContent) return control;
    return (
      <Tooltip content={tooltipContent} position={tooltipPosition}>
        {control}
      </Tooltip>
    );
  },
);

IconButton.displayName = 'IconButton';

const defaultBadgeLabel = (badge: number | string | true) => (badge === true ? ', new' : `, ${badge} new`);
